import 'dart:async';
import 'package:flutter/material.dart';
class WorkoutScreen extends StatefulWidget{const WorkoutScreen({super.key});@override State<WorkoutScreen> createState()=>_WorkoutScreenState();}
class _WorkoutScreenState extends State<WorkoutScreen>{int rest=0;Timer? timer;final sets=[false,false,false,false];void completeSet(int i){setState(()=>sets[i]=!sets[i]);if(sets[i])startRest();}void startRest(){timer?.cancel();setState(()=>rest=90);timer=Timer.periodic(const Duration(seconds:1),(t){if(rest<=1){t.cancel();setState(()=>rest=0);}else{setState(()=>rest--);}});}@override void dispose(){timer?.cancel();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Full Body A')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Dumbbell Bench Press',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const Text('Chest · Triceps · Shoulders',style:TextStyle(color:Colors.white60)),if(rest>0)Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('Rest ${rest~/60}:${(rest%60).toString().padLeft(2,'0')}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)))),...List.generate(sets.length,(i)=>CheckboxListTile(value:sets[i],onChanged:(_)=>completeSet(i),title:Text('Set ${i+1}'),subtitle:const Text('150 lb · 8 reps'))),FilledButton(onPressed:()=>showModalBottomSheet(context:context,builder:(c)=>const Padding(padding:EdgeInsets.all(24),child:Text('Rate difficulty before server-authoritative rewards are claimed.'))),child:const Text('Finish Workout'))]));}
